/bin/bash -lc "python - <<'PY'
import numpy as np
from collections import deque
A=np.load('source_pixels.npz')['rgb']
for t in range(96):
 im=A[t]; mask=(im[:,:,0]>180)&(im[:,:,0]>im[:,:,1]*1.25)&(im[:,:,0]>im[:,:,2]*1.2)
 # comps
 seen=np.zeros(mask.shape,bool); cs=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  st=[(y,x)]; seen[y,x]=1; pts=[]
  while st:
   yy,xx=st.pop();pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=yy+dy,xx+dx
     if 0<=ny<144 and 0<=nx<256 and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
  if len(pts)>=3:
   q=np.array(pts);cs.append((len(pts),round(q[:,1].mean(),1),round(q[:,0].mean(),1),q[:,1].min(),q[:,1].max(),q[:,0].min(),q[:,0].max()))
 if t%4==0 or t<10: print(t+1,sorted(cs,reverse=True)[:6])
PY"
